from solution import Entry, Report, solve

assert solve([], 0) == Report(0, 0, 0), 'fixture 0'
assert solve([], 5) == Report(0, 0, 0), 'fixture 1'
assert solve([], 1) == Report(0, 0, 0), 'fixture 2'
assert solve([Entry(3, 8, 3)], 2) == Report(1, 4, 8), 'fixture 3'
assert solve([Entry(1, 6, 3), Entry(3, 7, 5)], 3) == Report(2, 8, 13), 'fixture 4'
assert solve([Entry(2, 11, 1), Entry(0, 0, 6), Entry(0, (-2), 5)], 4) == Report(3, 8, 9), 'fixture 5'
assert solve([Entry(3, 10, 2), Entry(2, 2, 3), Entry(4, 0, 4), Entry(0, 11, 2)], 5) == Report(4, 38, 23), 'fixture 6'
assert solve([Entry(3, 10, 3), Entry(0, 5, 5), Entry(4, 2, 6), Entry(1, 3, 1), Entry(1, 1, 1)], 6) == Report(5, 42, 21), 'fixture 7'
assert solve([Entry(3, 5, 6), Entry(1, (-2), 5), Entry(3, 11, 6), Entry(4, 2, 4), Entry(0, 10, 6), Entry(3, 6, 5)], 7) == Report(6, 71, 32), 'fixture 8'
assert solve([Entry(1, 5, 1), Entry(1, 1, 1), Entry(3, (-1), 1), Entry(0, 8, 4), Entry(3, 7, 4), Entry(0, 5, 4), Entry(1, 11, 3)], 8) == Report(7, 69, 36), 'fixture 9'
assert solve([Entry(0, (-3), 3), Entry(1, 7, 4), Entry(1, 7, 1), Entry(3, (-2), 3), Entry(4, (-1), 4), Entry(0, 4, 5), Entry(2, 8, 4), Entry(1, (-2), 6)], 1) == Report(1, 3, 8), 'fixture 10'
assert solve([Entry(2, 10, 2), Entry(2, 11, 2), Entry(4, 2, 2), Entry(3, 1, 2), Entry(2, 1, 5), Entry(2, 4, 2), Entry(0, 2, 1), Entry(3, (-3), 4), Entry(4, 2, 2)], 2) == Report(2, 9, 21), 'fixture 11'
assert solve([Entry(0, 7, 1), Entry(3, (-3), 1), Entry(1, 5, 6), Entry(0, 10, 1), Entry(1, 8, 3), Entry(3, 6, 3), Entry(0, 2, 3), Entry(4, 5, 3), Entry(2, (-1), 2), Entry(0, 1, 2)], 3) == Report(3, 8, 25), 'fixture 12'
assert solve([Entry(2, 5, 3), Entry(4, 3, 6), Entry(3, 11, 1), Entry(1, 8, 6), Entry(3, 4, 2), Entry(0, 1, 1), Entry(4, 3, 2), Entry(1, 5, 6), Entry(4, 6, 5), Entry(1, 9, 5), Entry(4, 7, 2)], 4) == Report(4, 34, 35), 'fixture 13'
assert solve([Entry(1, 3, 2), Entry(1, 7, 2), Entry(3, 4, 6), Entry(2, 6, 3), Entry(2, 11, 3), Entry(1, 0, 5), Entry(0, 2, 2), Entry(1, 10, 3), Entry(1, (-1), 5), Entry(0, (-1), 1), Entry(3, 11, 6), Entry(3, (-3), 4)], 5) == Report(5, 40, 45), 'fixture 14'
assert solve([], 6) == Report(0, 0, 0), 'fixture 15'
assert solve([Entry(3, (-1), 5)], 7) == Report(1, 4, (-1)), 'fixture 16'
assert solve([Entry(0, 4, 1), Entry(4, 8, 4)], 8) == Report(2, 7, 12), 'fixture 17'
assert solve([Entry(3, 7, 3), Entry(0, (-1), 4), Entry(0, 3, 4)], 1) == Report(1, 4, 7), 'fixture 18'
assert solve([Entry(1, 11, 3), Entry(0, 5, 2), Entry(3, 4, 3), Entry(0, 4, 2)], 2) == Report(2, 4, 16), 'fixture 19'
assert solve([Entry(1, 1, 5), Entry(2, 5, 4), Entry(4, (-3), 3), Entry(2, 5, 5), Entry(1, (-3), 6)], 3) == Report(3, 15, 11), 'fixture 20'
assert solve([Entry(0, 4, 4), Entry(2, 1, 6), Entry(3, 10, 1), Entry(4, (-3), 1), Entry(2, 4, 1), Entry(1, 4, 6)], 4) == Report(4, 21, 22), 'fixture 21'
assert solve([Entry(2, 1, 6), Entry(0, 6, 5), Entry(1, 6, 5), Entry(0, 0, 5), Entry(1, 0, 2), Entry(2, 11, 1), Entry(4, (-1), 4)], 5) == Report(5, 33, 24), 'fixture 22'
assert solve([Entry(4, 6, 1), Entry(4, (-1), 1), Entry(0, (-3), 4), Entry(2, 9, 5), Entry(0, (-1), 2), Entry(0, 2, 2), Entry(1, (-2), 3), Entry(1, (-1), 6)], 6) == Report(6, 53, 14), 'fixture 23'
assert solve([Entry(8, 5, 2), Entry(1, 5, 2), Entry(3, 5, 1)], 2) == Report(2, 22, 10), 'fixture 24'
assert solve([Entry(9, 2, 1), Entry(3, 5, 4), Entry(4, 5, 4), Entry(8, 5, 2)], 2) == Report(2, 17, 10), 'fixture 25'
